command:
set -eu
BASE=/workspace/omega_runtime/extensions/ingress_v5
LOG=/workspace/omega_runtime/state/logs/ingress_gateway_v5.log
umask 077
tmux new-session -d -s omega-ingress-v5-canary "cd $BASE && PYTHONPATH=. exec python3 -m omega.ingress_gateway serve --owner gabriel --machine omega-vps --port 8788 >>$LOG 2>&1"
python3 - <<'PY'
import urllib.request,time
from pathlib import Path
t=Path('/workspace/omega_runtime/private/ingress-gabriel.token').read_text().strip()
r=urllib.request.Request('http://127.0.0.1:8788/v1/health',headers={'Authorization':'Bearer '+t})
for _ in range(15):
 try:
  with urllib.request.urlopen(r,timeout=2) as x: print('CANARY_V5',x.status);break
 except Exception:time.sleep(.2)
else:raise AssertionError('v5 candidate unavailable')
PY
tmux kill-session -t omega-ingress-v5-canary
tmux has-session -t omega-ingress
tmux kill-session -t omega-ingress
tmux new-session -d -s omega-ingress "cd $BASE && PYTHONPATH=. exec python3 -m omega.ingress_gateway serve --owner gabriel --machine omega-vps --port 8787 >>$LOG 2>&1"
python3 - <<'PY'
import urllib.request,urllib.error,time
from pathlib import Path
t=Path('/workspace/omega_runtime/private/ingress-gabriel.token').read_text().strip()
r=urllib.request.Request('http://127.0.0.1:8787/v1/health',headers={'Authorization':'Bearer '+t})
for _ in range(18):
 try:
  with urllib.request.urlopen(r,timeout=2) as x: print('ACTIVE_V5',x.status);break
 except Exception:time.sleep(.2)
else:raise AssertionError('v5 not ready')
try:urllib.request.urlopen('http://127.0.0.1:8787/v1/health',timeout=2)
except urllib.error.HTTPError as e:
 print('NO_TOKEN',e.code); assert e.code==401
else:raise AssertionError('auth bypass')
PY
